        print(f"Target State Space: {TARGET_COUNT}")

    except OverflowError as oe:
        sys.stderr.write(f"Critical Overflow: {oe}\n")
        sys.exit(1)
    except MemoryError as me:
        sys.stderr.write(f"Resource Exhaustion: {me}\n")
        sys.exit(1)
